60	{
61	    return json{{"id", spool.id},
62	                {"printer_preset", spool.printer_preset},
63	                {"filament_preset", spool.filament_preset},
64	                {"colour", spool.colour},
65	                {"name", spool.name},
66	                {"brand", spool.brand},
67	                {"last_used", spool.last_used}};
68	}
