72	SpoolStore::SpoolStore(Config config) : m_config(std::move(config))
73	{
74	    if (m_config.file_path.empty())
75	        throw std::invalid_argument("SpoolStore requires a file path");
76	    if (!m_config.clock)
77	        m_config.clock = default_clock;
78	    if (!m_config.uuid)
79	        m_config.uuid = default_uuid;
80	
81	    const fs::path path(m_config.file_path);
82	    std::error_code ec;
83	    if (!fs::exists(path, ec))
84	        return;
85	
86	    std::string text;
87	    {
88	        std::ifstream in(path, std::ios::binary);
89	        if (!in.is_open()) {
90	            m_corrupt        = true;
91	            m_corrupt_reason = "spools file could not be opened";
92	            return;
93	        }
94	        std::stringstream buffer;
95	        buffer << in.rdbuf();
96	        text = buffer.str();
97	    }
98	
99	    // A damaged file is data the person cannot get back. Parse defensively
100	    // here -- and only here -- then move the file aside so the next write
101	    // cannot overwrite it. Everything past this point treats the in-memory
102	    // vector as authoritative.
103	    try {
104	        const json document = json::parse(text);
105	        for (const auto& entry : document.at("spools"))
106	            m_spools.push_back(spool_from(entry));
107	    } catch (const json::exception& error) {
108	        m_spools.clear();
109	        m_corrupt        = true;
110	        m_corrupt_reason = error.what();
111	    }
112	
113	    if (m_corrupt) {
114	        /* MUTANT: no move */
115	        if (ec)
116	            m_corrupt_reason += "; the damaged file could not be moved aside: " + ec.message();
117	    }
118	}
