120	std::vector<Spool> SpoolStore::spools_for(const std::string& printer_preset) const
121	{
122	    std::vector<Spool> matches;
123	    for (const Spool& spool : m_spools)
124	        if (spool.printer_preset == printer_preset)
125	            matches.push_back(spool);
126	    std::sort(matches.begin(), matches.end(), [](const Spool& a, const Spool& b) {
127	        if (a.last_used != b.last_used)
128	            return a.last_used < b.last_used; // MUTANT
129	        return a.id < b.id;
130	    });
131	    return matches;
132	}
