134	std::optional<Spool> SpoolStore::current(const std::string& printer_preset,
135	                                         const std::string& filament_preset,
136	                                         const std::string& colour) const
137	{
138	    // Most recently used wins when two spools of the same preset share a
139	    // colour, which is the same order the menu shows.
140	    for (const Spool& spool : spools_for(printer_preset))
141	        if (spool.filament_preset == filament_preset && spool.colour == colour)
142	            return spool;
143	    return std::nullopt;
