201	void SpoolStore::write()
202	{
203	    json document;
204	    document["version"] = kSchemaVersion;
205	    document["spools"]  = json::array();
206	    for (const Spool& spool : m_spools)
207	        document["spools"].push_back(json_from(spool));
208	
209	    const fs::path path(m_config.file_path);
210	    std::error_code ec;
211	    fs::create_directories(path.parent_path(), ec);
212	
213	    const fs::path temp = path.string() + ".tmp";
214	    {
215	        std::ofstream out(temp, std::ios::binary | std::ios::trunc);
216	        if (!out.is_open())
217	            throw std::runtime_error("could not open " + temp.string() + " to save spools");
218	        out << document.dump(2);
219	        if (!out.good())
220	            throw std::runtime_error("could not write " + temp.string());
221	    }
222	    fs::rename(temp, path, ec);
223	    if (ec)
224	        throw std::runtime_error("could not save spools to " + path.string() + ": " + ec.message());
225	}
