89	std::vector<NozzleVariant> nozzle_variants()
90	{
91	    std::vector<NozzleVariant> variants;
92	    const PresetBundle* presets = wxGetApp().preset_bundle;
93	    if (presets == nullptr)
94	        return variants;
95	    const Preset&     edited = presets->printers.get_edited_preset();
96	    const std::string model  = edited.config.opt_string("printer_model");
97	    if (model.empty())
98	        return variants;
99	
100	    for (const Preset& preset : presets->printers) {
101	        if (!preset.is_visible || preset.is_default)
102	            continue;
103	        if (preset.config.opt_string("printer_model") != model)
104	            continue;
105	        const auto* nozzle = preset.config.option<ConfigOptionFloats>("nozzle_diameter");
106	        if (nozzle == nullptr || nozzle->values.empty())
107	            continue;
108	        variants.push_back({preset.name, nozzle->values.front(), preset.name == edited.name});
109	    }
110	    std::sort(variants.begin(), variants.end(),
111	              [](const NozzleVariant& a, const NozzleVariant& b) { return a.nozzle < b.nozzle; });
112	    // One variant is not a choice; the row shows the value without a submenu.
113	    if (variants.size() < 2)
114	        variants.clear();
115	    return variants;
