137	            // enum_values is 0-based over the labels that follow btDefault.
138	            const int index = int(type) - 1;
139	            if (index >= 0 && index < int(definition->enum_labels.size()))
140	                label = _(definition->enum_labels[index]);
141	        }
142	        if (label.empty())
143	            label = wxString::Format("%d", int(type));
144	        choices.push_back({int(type), label, type == current});
